14	const BASE_PREMIUMS: Record<string, number> = {
15	  sword: 100,
16	  amulet: 60,
17	  staff: 80,
18	  potion: 40,
19	  rune: 25,
20	  moonstone: 25,
21	};
22	
23	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
24	const PROCESSING_FEE = 5;
25	
26	const CURSE_SURCHARGE_RATE = 0.5;
27	const HIGH_ENCHANTMENT_THRESHOLD = 5;
28	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
29	const LOYALTY_THRESHOLD_YEARS = 2;
30	const LOYALTY_DISCOUNT_RATE = 0.2;
31	
32	const BLOCK_SIZE = 3;
33	const BLOCK_BASE_PREMIUM = 60;
34	
35	const countByType = (items: Item[]): Map<string, number> => {
36	  const counts = new Map<string, number>();
37	  for (const item of items) {
38	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
39	  }
40	  return counts;
41	};
42	
43	const basePremiumForType = (type: string, count: number): number =>
44	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
45	
46	const policyBasePremium = (items: Item[]): number =>
47	  [...countByType(items)]
48	    .map(([type, count]) => basePremiumForType(type, count))
49	    .reduce((total, premium) => total + premium, 0);
50	
51	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
52	
53	const isCursed = (item: Item): boolean => item.cursed === true;
54	
55	const isHighlyEnchanted = (item: Item): boolean =>
56	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
57	
58	const curseSurcharge = (item: Item): number =>
59	  isCursed(item) ? itemBasePremium(item) * CURSE_SURCHARGE_RATE : 0;
60	
61	const highEnchantmentSurcharge = (item: Item): number =>
62	  isHighlyEnchanted(item)
63	    ? itemBasePremium(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
64	    : 0;
65	
66	const itemModifierSurcharges = (items: Item[]): number =>
67	  items
68	    .map((item) => curseSurcharge(item) + highEnchantmentSurcharge(item))
69	    .reduce((total, surcharge) => total + surcharge, 0);
70	
71	const isLoyalCustomer = (customer: Customer): boolean =>
72	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
73	
74	const quotePremium = (customer: Customer, items: Item[] = []): number => {
75	  const policyBase = policyBasePremium(items);
76	  const itemSurcharges = itemModifierSurcharges(items);
77	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
78	  const loyaltyDiscount = isLoyalCustomer(customer)
79	    ? policyBase * LOYALTY_DISCOUNT_RATE
80	    : 0;
81	  return Math.ceil(
82	    policyBase +
83	      itemSurcharges +
84	      firstInsuranceSurcharge -
85	      loyaltyDiscount +
86	      PROCESSING_FEE,
87	  );
88	};
89	
90	export const runScenario = (scenario: Scenario): ScenarioResult => ({
91	  results: scenario.steps.map((step) => ({
92	    premium: quotePremium(scenario.customer, step.items),
93	  })),
94	});
