  const policyBase = policyBasePremium(items);
  const itemSurcharges = itemModifierSurcharges(items);
  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
  const loyaltyDiscount = isLoyalCustomer(customer)
    ? policyBase * LOYALTY_DISCOUNT_RATE
