// Policy-wide modifiers are rates applied to the policy base premium.
// Surcharges are positive, discounts negative; they sum to one net rate.
const policyModifierRates = (customer: Customer): number[] => [
  FIRST_INSURANCE_SURCHARGE_RATE,
  isLoyalCustomer(customer) ? -LOYALTY_DISCOUNT_RATE : 0,
];

const netPolicyModifierRate = (customer: Customer): number =>
  policyModifierRates(customer).reduce((total, rate) => total + rate, 0);

const quotePremium = (customer: Customer, items: Item[] = []): number => {
  const policyBase = policyBasePremium(items);
  const policyModifiers = policyBase * netPolicyModifierRate(customer);
  return Math.ceil(
    policyBase + itemModifierSurcharges(items) + policyModifiers + PROCESSING_FEE,
  );
};
